#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ───────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

banner "Finance Assistant private-demo qualification"

REPOSITORY="hankgalt/ai_finance_assitant"
PROJECT_ID="comfforts-369117"
PROJECT_NUMBER="730340912967"
REGION="us-west1"
OWNER_ACCOUNT="vtalwar.w@comfforts.com"
OWNER_MEMBER="user:$OWNER_ACCOUNT"
BACKEND_SERVICE="aifa-staging-backend"
FRONTEND_SERVICE="aifa-staging-frontend"
EDGE_BACKEND_SERVICE="aifa-staging-backend-edge"
EDGE_FRONTEND_SERVICE="aifa-staging-frontend-edge"
CERTIFICATE_NAME="aifa-staging-edge-certificate"
IAP_SERVICE_AGENT="service-${PROJECT_NUMBER}@gcp-sa-iap.iam.gserviceaccount.com"
REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)
EVIDENCE_ROOT="$REPO_ROOT/backend/artifacts/release/deployment"
REQUIRED_EVIDENCE=(
  "backend/artifacts/release/deployment/demo-runtime-lifecycle.v1.json"
  "backend/artifacts/release/deployment/application-workloads.v1.json"
  "backend/artifacts/knowledge/deployment/staging-release-a737f8e9e935f8afc05e16fc7148e3a185b32086.json"
  "backend/artifacts/knowledge/deployment/staging-runtime-key-rotation-86146b6227285015665b84cbfa3f4ce0395cd618-v1-to-v2.json"
  "backend/artifacts/release/deployment/private-edge-3327a231fcc197d4a8032de7b8a30523fecc1eda.v1.json"
)
TEMP_FILES=()

# Remove only temporary evidence assembly files. Playwright owns and removes its
# temporary browser profile; no authentication state is copied to the repository.
cleanup_temp() {
  local path
  for path in "${TEMP_FILES[@]}"; do
    [[ -e "$path" ]] && rm -f "$path"
  done
}
trap cleanup_temp EXIT

# Produce a portable SHA-256 for already-committed evidence without modifying it.
sha256_file() {
  if command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$1" | awk '{print $1}'
  else
    sha256sum "$1" | awk '{print $1}'
  fi
}

# Require the exact ready/private Cloud Run posture qualified by the workload slice.
verify_private_service() {
  local service="$1" description iam direct_url direct_path
  description=$(gcloud run services describe "$service" \
    --project="$PROJECT_ID" --region="$REGION" --format=json)
  jq -e '
    .metadata.annotations["run.googleapis.com/ingress"] == "internal-and-cloud-load-balancing" and
    .metadata.annotations["run.googleapis.com/default-url-disabled"] == "true" and
    any(.status.conditions[]?; .type == "Ready" and .status == "True")
  ' <<<"$description" >/dev/null || {
    warn "$service is not Ready with the required private ingress and disabled default URL"
    return 1
  }
  iam=$(gcloud run services get-iam-policy "$service" \
    --project="$PROJECT_ID" --region="$REGION" --format=json)
  jq -e --arg iap_agent "serviceAccount:$IAP_SERVICE_AGENT" '
    [.bindings[]? | select(.role == "roles/run.invoker") | .members[]?] == [$iap_agent] and
    all(.bindings[]?.members[]?; . != "allUsers" and . != "allAuthenticatedUsers")
  ' <<<"$iam" >/dev/null || {
    warn "$service does not have the exact IAP-service-agent-only invocation boundary"
    return 1
  }
  direct_url=$(jq -r '.status.url // empty' <<<"$description")
  if [[ -n "$direct_url" ]]; then
    direct_path="/api/health/live"
    [[ "$service" == "$FRONTEND_SERVICE" ]] && direct_path="/finance_assistant/healthz"
    if curl --silent --show-error --fail --max-time 15 "$direct_url$direct_path" \
      >/dev/null 2>&1; then
      warn "$service accepted direct anonymous traffic"
      return 1
    fi
  fi
  printf '%s' "$description"
}

# Recheck the owner-only IAP admission policy without changing it.
verify_edge_policy() {
  local service="$1" description edge_id policy
  description=$(gcloud compute backend-services describe "$service" \
    --project="$PROJECT_ID" --global --format=json)
  jq -e '.iap.enabled == true and (.iap.oauth2ClientId | length > 0)' \
    <<<"$description" >/dev/null || return 1
  edge_id=$(jq -er '.id | tostring' <<<"$description")
  policy=$(gcloud iap web get-iam-policy \
    --project="$PROJECT_ID" --resource-type=backend-services \
    --service="$edge_id" --format=json)
  jq -e --arg owner "$OWNER_MEMBER" '
    [.bindings[]? | select(.role == "roles/iap.httpsResourceAccessor") | .members[]?] == [$owner] and
    all(.bindings[]?.members[]?; . != "allUsers" and . != "allAuthenticatedUsers")
  ' <<<"$policy" >/dev/null
}

# ── Stage 1: local identity, repository, and tool preflight ───────────
stage "Verify merged main and operator identities"
for tool in git gh gcloud jq pnpm curl awk install; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is required"; exit 1; }
done
if ! command -v shasum >/dev/null 2>&1 && ! command -v sha256sum >/dev/null 2>&1; then
  warn "shasum or sha256sum is required"
  exit 1
fi
cd "$REPO_ROOT"
[[ "$(git branch --show-current)" == "main" ]] || { warn "switch to main first"; exit 1; }
[[ -z "$(git status --porcelain)" ]] || { warn "main must be clean"; exit 1; }
git fetch origin main --quiet
[[ "$(git rev-parse HEAD)" == "$(git rev-parse origin/main)" ]] || {
  warn "main must be fast-forwarded to origin/main"
  exit 1
}
gh auth status >/dev/null 2>&1 || { warn "authenticate gh first"; exit 1; }
[[ "$(gh api user --jq .login)" == "hankgalt" ]] || { warn "gh must use hankgalt"; exit 1; }
ACTIVE_ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)')
[[ "$ACTIVE_ACCOUNT" == "$OWNER_ACCOUNT" ]] || {
  warn "gcloud must use $OWNER_ACCOUNT, not ${ACTIVE_ACCOUNT:-none}"
  exit 1
}
[[ "$(gcloud config get-value project 2>/dev/null)" == "$PROJECT_ID" ]] || {
  warn "gcloud project must be $PROJECT_ID"
  exit 1
}
REVISION=$(git rev-parse HEAD)
EVIDENCE_FILE="$EVIDENCE_ROOT/private-demo-${REVISION}.v1.json"
[[ ! -e "$EVIDENCE_FILE" ]] || {
  warn "qualified evidence already exists for $REVISION; no second live run will overwrite it"
  exit 1
}
say "Qualifying clean merged revision $REVISION."

# ── Stage 2: read-only live infrastructure and provider-boundary checks ───
stage "Verify the live private deployment boundary"
BACKEND_IMAGE=$(gh variable get GCP_BACKEND_IMAGE --repo "$REPOSITORY" --env staging)
FRONTEND_IMAGE=$(gh variable get GCP_FRONTEND_IMAGE --repo "$REPOSITORY" --env staging)
for image in "$BACKEND_IMAGE" "$FRONTEND_IMAGE"; do
  [[ "$image" == us-west1-docker.pkg.dev/comfforts-369117/aifa-containers/*@sha256:* ]] || {
    warn "staging image variables must be Artifact Registry digest references"
    exit 1
  }
  gcloud artifacts docker images describe "$image" --project="$PROJECT_ID" >/dev/null
done
BACKEND_DESCRIPTION=$(verify_private_service "$BACKEND_SERVICE")
FRONTEND_DESCRIPTION=$(verify_private_service "$FRONTEND_SERVICE")
BACKEND_DEPLOYED_IMAGE=$(jq -er \
  '.spec.template.spec.containers[] | select(.name == "backend") | .image' \
  <<<"$BACKEND_DESCRIPTION")
FRONTEND_DEPLOYED_IMAGE=$(jq -er \
  '.spec.template.spec.containers[] | select(.name == "frontend") | .image' \
  <<<"$FRONTEND_DESCRIPTION")
[[ "$BACKEND_DEPLOYED_IMAGE" == "$BACKEND_IMAGE" ]] || { warn "backend image mismatch"; exit 1; }
[[ "$FRONTEND_DEPLOYED_IMAGE" == "$FRONTEND_IMAGE" ]] || { warn "frontend image mismatch"; exit 1; }
jq -e '
  [.spec.template.spec.containers[] | select(.name == "backend") | .env[]?] as $env |
  any($env[]; .name == "AIFA_PROVIDER_MODE" and .value == "credential_free") and
  any($env[]; .name == "AIFA_MODEL_MODE" and .value == "credential_free") and
  any($env[]; .name == "AIFA_RESPONSE_CACHE_ADAPTER" and .value == "disabled") and
  all($env[]; .name != "AIFA_ALPHA_VANTAGE_API_KEY" and
              .name != "AIFA_MASSIVE_API_KEY" and
              .name != "AIFA_OPENAI_API_KEY" and
              .name != "AIFA_TAVILY_API_KEY" and
              .name != "OPENAI_API_KEY")
' <<<"$BACKEND_DESCRIPTION" >/dev/null || {
  warn "the backend is not at the approved credential-free provider boundary"
  exit 1
}
for edge_service in "$EDGE_BACKEND_SERVICE" "$EDGE_FRONTEND_SERVICE"; do
  verify_edge_policy "$edge_service" || { warn "$edge_service IAP policy mismatch"; exit 1; }
done
[[ "$(gcloud compute ssl-certificates describe "$CERTIFICATE_NAME" \
  --project="$PROJECT_ID" --global --format='value(managed.status)')" == "ACTIVE" ]] || {
  warn "the managed certificate is not ACTIVE"
  exit 1
}
say "Images, private origins, owner-only IAP, TLS, and credential-free modes are intact."

# ── Stage 3: deterministic gates and prior evidence aggregation ─────────
stage "Recheck isolation contracts and prior evidence"
for evidence in "${REQUIRED_EVIDENCE[@]}"; do
  [[ -f "$REPO_ROOT/$evidence" ]] || { warn "missing required evidence: $evidence"; exit 1; }
  jq -e '.schema_version == "1" and (.status | length > 0)' \
    "$REPO_ROOT/$evidence" >/dev/null || { warn "invalid evidence: $evidence"; exit 1; }
done
"$REPO_ROOT/backend/.venv/bin/python" -m pytest -q \
  "$REPO_ROOT/backend/tests/test_identity_access.py" \
  "$REPO_ROOT/backend/tests/test_managed_persistence.py" \
  "$REPO_ROOT/backend/tests/test_private_edge.py" \
  "$REPO_ROOT/backend/tests/test_private_demo_qualification.py" \
  "$REPO_ROOT/backend/tests/test_release_bundle.py"
PRIOR_EVIDENCE_FILE=$(mktemp "${TMPDIR:-/tmp}/aifa-prior-evidence.XXXXXX")
TEMP_FILES+=("$PRIOR_EVIDENCE_FILE")
printf '[]\n' > "$PRIOR_EVIDENCE_FILE"
for evidence in "${REQUIRED_EVIDENCE[@]}"; do
  evidence_hash=$(sha256_file "$REPO_ROOT/$evidence")
  updated=$(mktemp "${TMPDIR:-/tmp}/aifa-prior-evidence-update.XXXXXX")
  TEMP_FILES+=("$updated")
  jq --arg path "$evidence" --arg sha256 "$evidence_hash" \
    '. + [{path: $path, sha256: $sha256}]' "$PRIOR_EVIDENCE_FILE" > "$updated"
  cp "$updated" "$PRIOR_EVIDENCE_FILE"
done
say "The signed-IAP/two-Principal matrix and five prerequisite evidence records pass."

# ── Stage 4: interactive IAP login and real product journeys ────────────
stage "Run the authenticated product journeys"
say "Playwright opens a temporary Chrome context at the protected URL."
step "Complete Google/IAP sign-in only in that Chrome window when prompted."
step "Do not paste a password, MFA code, cookie, token, or secret into this terminal."
step "The automated journey creates only synthetic records and deletes them before success."
confirm "Start the owner-only credential-free browser qualification now?" || exit 1
RAW_EVIDENCE=$(mktemp "${TMPDIR:-/tmp}/aifa-private-demo-evidence.XXXXXX")
TEMP_FILES+=("$RAW_EVIDENCE")
(
  cd "$REPO_ROOT/frontend"
  AIFA_RUN_DEPLOYED_QUALIFICATION=true \
  AIFA_DEPLOYMENT_REVISION="$REVISION" \
  AIFA_DEPLOYMENT_EVIDENCE_TEMP="$RAW_EVIDENCE" \
  AIFA_PRIOR_EVIDENCE_FILE="$PRIOR_EVIDENCE_FILE" \
  AIFA_DEPLOYED_BACKEND_IMAGE="$BACKEND_DEPLOYED_IMAGE" \
  AIFA_DEPLOYED_FRONTEND_IMAGE="$FRONTEND_DEPLOYED_IMAGE" \
    pnpm exec playwright test --config playwright.deployment.config.ts
)

# ── Stage 5: validate and publish only secret-free evidence ────────────
stage "Validate the qualification evidence"
jq -e \
  --arg revision "$REVISION" \
  --arg backend "$BACKEND_DEPLOYED_IMAGE" \
  --arg frontend "$FRONTEND_DEPLOYED_IMAGE" '
    .schema_version == "1" and
    .status == "qualified" and
    .qualification_revision == $revision and
    .target == "https://apps.comfforts.com/finance_assistant" and
    .deployed_images == {backend: $backend, frontend: $frontend} and
    .provider_boundary == {
      provider_mode: "credential_free",
      model_mode: "credential_free",
      live_provider_secrets_present: false
    } and
    (.prior_evidence | length) == 5 and
    all(.prior_evidence[]; (.sha256 | test("^[0-9a-f]{64}$"))) and
    all(.journeys[]; startswith("passed")) and
    .secret_payloads_recorded == false
  ' "$RAW_EVIDENCE" >/dev/null || {
  warn "browser output does not satisfy the private-demo evidence contract"
  exit 1
}
say "The browser result satisfies the private-demo evidence contract."

# ── Stage 6: final readback and evidence handoff ─────────────────────
stage "Confirm unchanged cloud boundaries and hand off evidence"
FINAL_BACKEND=$(gcloud run services describe "$BACKEND_SERVICE" \
  --project="$PROJECT_ID" --region="$REGION" --format=json | jq -er \
  '.spec.template.spec.containers[] | select(.name == "backend") | .image')
FINAL_FRONTEND=$(gcloud run services describe "$FRONTEND_SERVICE" \
  --project="$PROJECT_ID" --region="$REGION" --format=json | jq -er \
  '.spec.template.spec.containers[] | select(.name == "frontend") | .image')
[[ "$FINAL_BACKEND" == "$BACKEND_DEPLOYED_IMAGE" ]] || { warn "backend changed during run"; exit 1; }
[[ "$FINAL_FRONTEND" == "$FRONTEND_DEPLOYED_IMAGE" ]] || { warn "frontend changed during run"; exit 1; }
for edge_service in "$EDGE_BACKEND_SERVICE" "$EDGE_FRONTEND_SERVICE"; do
  verify_edge_policy "$edge_service" || { warn "$edge_service changed during run"; exit 1; }
done
install -m 0644 "$RAW_EVIDENCE" "$EVIDENCE_FILE"
say "Wrote secret-free revision-scoped evidence:"
say "$EVIDENCE_FILE"
say "The qualification performed no infrastructure, IAM, DNS, secret, or provider-mode writes."
warn "Commit the generated evidence on a dedicated branch, then reconcile ADR-030 and the MVP report."

finish
}

run_wizard "$@"; exit
